#!/usr/bin/env python3
"""Generate both static language pages. Standard library only; no runtime framework."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CHECK = argparse.ArgumentParser()
CHECK.add_argument('--check', action='store_true')
args = CHECK.parse_args()

# Booking page (Cal.com / Calendly). Empty: consultation CTAs lead to the contact form.
BOOKING_URL = ''
# Client testimonials. Publish only real quotes approved by the client; the section renders when the list is not empty.
# dict(quote=('PL', 'EN'), name='Imię Nazwisko', role=('Właściciel', 'Owner'), company='Firma')
TESTIMONIALS = []


def render(lang):
    def t(pl, en): return pl if lang == 'pl' else en
    def tags(items): return ''.join(f'<span>{s}</span>' for s in items)
    arrow = '<span aria-hidden="true">↗</span>'
    url = 'https://mleczakm.github.io/' + ('en/' if lang == 'en' else '')
    title = t('Michał Mleczko — AI w firmie, automatyzacja i szybkie strony', 'Michał Mleczko — Business AI, automation & fast websites')
    desc = t('Zastępuję kosztowne, ręczne procesy dedykowanym oprogramowaniem i agentami AI. Technologiczny partner od analizy, przez wdrożenie, po utrzymanie: automatyzacje, MCP, sklepy z BLIK i szybkie strony bez WordPressa.', 'I replace costly manual processes with dedicated software and AI agents. A technology partner from analysis through launch to ongoing support: automation, MCP, BLIK commerce and fast websites without WordPress.')
    book = BOOKING_URL or '#contact'
    book_attrs = ' target="_blank" rel="noopener noreferrer"' if BOOKING_URL else ''
    nav = [('ai', t('AI w firmie', 'Business AI')), ('projects', t('Realizacje', 'Selected work')), ('wordpress', 'WordPress → Static'), ('about', t('O mnie', 'About'))]
    navigation = ''.join(f'<a href="#{key}">{label}</a>' for key, label in nav)
    services = [
        ('01', t('Od procesu do działającego AI', 'From workflow to working AI'), t('Wybieram z zespołem zadania, w których AI ma sens. Ustalamy punkt wyjścia, koszt i kryteria sukcesu, a potem sprawdzamy je w pilotażu.', 'Together with your team, I find the tasks where AI makes sense. We define a baseline, cost and success criteria, then validate them in a pilot.')),
        ('02', t('Agenci połączeni z Twoją firmą', 'Agents connected to your business'), t('Łączę asystentów z ofertą, rezerwacjami, zadaniami i firmową wiedzą przez MCP oraz API. Rozmowa może prowadzić do wykonania konkretnej pracy.', 'I connect assistants to your catalog, bookings, tasks and company knowledge through MCP and APIs. A conversation can lead to getting real work done.')),
        ('03', t('Kontrola po stronie człowieka', 'People stay in control'), t('Projektuję zakresy dostępu, potwierdzanie istotnych operacji i historię zmian. Agent działa w granicach uprawnień użytkownika.', 'I design access scopes, confirmation for consequential actions and change history. Agents work within each user’s permissions.')),
        ('04', t('Wdrożenie, które zostaje z zespołem', 'An implementation your team can own'), t('Integracje, testy, monitoring i dokumentacja. Wprowadzam zespół w nowy sposób pracy i pomagam rozwijać rozwiązanie po uruchomieniu.', 'Integrations, tests, monitoring and documentation. I help your team adopt the new workflow and improve it after launch.')),
    ]
