    projects = [
        dict(cls='sprint', url='https://sprintspaces.github.io/', name='SprintSpaces', label=t('PROCESY FIRMOWE · AI · MCP', 'BUSINESS WORKFLOWS · AI · MCP'), image=f'<img src="/assets/sprintspaces.webp" width="1554" height="1023" loading="lazy" alt="{t("Tablica SprintSpaces z przykładowymi zadaniami", "SprintSpaces board with sample tasks; Polish interface")}">',
             kpi=('1', t('miejsce zamiast arkuszy i maili', 'place instead of spreadsheets and email')),
             problem=t('Projekty, zgłoszenia i czas pracy rozproszone w arkuszach i mailach. Żeby poznać stan prac, trzeba kogoś zapytać.', 'Projects, tickets and time logs scattered across spreadsheets and email. Finding out where work stands means asking someone.'),
             solution=t('Wspólna przestrzeń pracy zintegrowana z Microsoft 365 i asystent AI, który przez MCP odczytuje i porządkuje zadania.', 'A shared workspace integrated with Microsoft 365, plus an AI assistant that reads and organizes tasks through MCP.'),
             result=t('Stan projektów i czas pracy w jednym miejscu. Pytanie „co czeka na moją decyzję?” zadajesz asystentowi, a nie zespołowi.', 'Project status and time tracking in one place. You ask the assistant “what’s waiting for my decision?” instead of interrupting your team.'),
             chips=['Go', 'Microsoft 365', 'MCP']),
        dict(cls='ceramiza', url='https://ceramiza.pl', name='Ceramiza', label=t('E-COMMERCE · BLIK · AI', 'E-COMMERCE · BLIK · AI'), image='<div class="ceramiza-art"><img src="/assets/ceramiza.jpg" width="450" height="450" loading="lazy" alt="Ceramiza"><span class="art-caption">handmade · one of a kind</span></div>',
             kpi=('0 zł' if lang == 'pl' else 'PLN 0', t('opłat dla operatora płatności', 'in payment-provider fees')),
             problem=t('Każda lampka jest jedyna, więc nie można sprzedać jej dwa razy. Klasyczny operator płatności to umowa i prowizja od każdej transakcji, a ręczne nadawanie paczek zjada czas.', 'Every lamp is one of a kind, so it can never be sold twice. A traditional payment provider means a contract and a fee on every sale, and shipping parcels by hand eats up time.'),
             solution=t('Sklep, który rezerwuje sztukę przy zamówieniu, przyjmuje BLIK na telefon z automatycznym dopasowaniem wpłat, nadaje paczki przez Polkurier i przyjmuje zamówienia w rozmowie z AI.', 'A shop that reserves each piece at checkout, accepts BLIK phone transfers with automatic payment matching, ships through Polkurier and takes orders in a conversation with AI.'),
             result=t('Zero opłat dla operatora płatności. Wpłata sama potwierdza zamówienie, etykieta drukuje się jednym kliknięciem, a status „wysłane” ustawia się automatycznie.', 'No payment-provider fees. Each payment confirms its order automatically, labels print in one click and the “shipped” status updates itself.'),
             chips=['Go', 'SQLite', 'ElevenLabs']),
        dict(cls='kiddo', url='https://warsztatowniasensoryczna.pl', name='Warsztatownia Sensoryczna', label=t('REZERWACJE · ASYSTENT AI', 'BOOKINGS · AI ASSISTANT'), image=f'<div class="workshop-art"><div class="workshop-flower" aria-hidden="true">✳</div><strong>{t("Małe odkrycia.<br>Wielkie możliwości.", "Little discoveries.<br>Big possibilities.")}</strong><span>{t("Zajęcia · karnety · rezerwacje", "Workshops · passes · bookings")}</span></div>',
             kpi=('24/7', t('zapisy i płatności bez udziału obsługi', 'bookings and payments without staff involvement')),
             problem=t('Grafik, wolne miejsca, karnety, odrabianie zajęć i płatności. Przy ręcznej obsłudze każda zmiana to wiadomość, telefon i wpis w notesie.', 'Schedules, available places, passes, make-up classes and payments. Handled manually, every change means a message, a call and a note to update.'),
             solution=t('System rezerwacji z karnetami i płatnościami BLIK, przypomnieniami e-mail z kalendarzem .ics oraz asystentem AI, który zapisuje na zajęcia w rozmowie.', 'A booking system with passes and BLIK payments, email reminders with .ics calendar files and an AI assistant that books workshops in conversation.'),
             result=t('Rodzice zapisują się i płacą sami, o każdej porze. Prowadzący dostaje gotową listę uczestników zamiast skrzynki pełnej wiadomości.', 'Parents book and pay on their own, at any hour. The team gets a ready list of participants instead of an inbox full of messages.'),
             chips=['Symfony', 'PostgreSQL', 'MCP']),
        dict(cls='cargo', url='https://cargo.mleczki.pl', name='Cargo · mleczki.pl', label=t('WYPOŻYCZALNIA · AUTOMATYZACJA', 'RENTALS · AUTOMATION'), image=f'<img src="/assets/cargo.webp" width="800" height="600" loading="lazy" alt="{t("Rower cargo Urban Arrow Family", "Urban Arrow Family cargo bike")}">',
             kpi=('~30 s', t('od przelewu BLIK do potwierdzonej rezerwacji', 'from BLIK transfer to confirmed booking')),
             problem=t('Wypożyczalnia żyje z kalendarza. Ustalanie terminów przez telefon i pilnowanie zaliczek zabiera czas i grozi podwójną rezerwacją.', 'A rental business lives by its calendar. Arranging dates by phone and chasing deposits takes time and risks double bookings.'),
             solution=t('Kalendarz dostępności sprzętu i dodatków, płatność BLIK z góry oraz panel zamówień, klientów i blokad terminów.', 'An availability calendar for equipment and add-ons, upfront BLIK payment and a dashboard for orders, customers and blocked dates.'),
             result=t('Klient sam wybiera sprzęt i dni, płaci, a rezerwacja potwierdza się automatycznie — bez telefonu i bez nakładających się terminów.', 'Customers choose equipment and dates, pay, and the booking confirms itself — no phone calls and no overlapping reservations.'),
             chips=['Go', 'SQLite', 'BLIK']),
    ]
    # kpi: only figures that are true for the project today. Replace with measured client results (hours saved, cost change) once confirmed.
    case_labels = (t('Problem', 'Problem'), t('Rozwiązanie', 'Solution'), t('Rezultat', 'Outcome'))
    def case_steps(*texts): return '<dl class="case-steps">' + ''.join(f'<div><dt>{label}</dt><dd>{text}</dd></div>' for label, text in zip(case_labels, texts)) + '</dl>'
    project_html = ''.join(f'''<article class="project-card"><a class="project-visual {p['cls']}" href="{p['url']}" target="_blank" rel="noopener noreferrer" aria-label="{t('Otwórz', 'Visit')} {p['name']} ({t('nowa karta', 'new tab')})">{p['image']}<span class="project-open" aria-hidden="true">↗</span></a><div class="project-info"><p class="eyebrow">{p['label']}</p><h3><a href="{p['url']}" target="_blank" rel="noopener noreferrer">{p['name']} {arrow}</a></h3><div class="case-kpi"><strong>{p['kpi'][0]}</strong><span>{p['kpi'][1]}</span></div>{case_steps(p['problem'], p['solution'], p['result'])}<div class="case-stack">{t('Technologia', 'Built with')}: {' · '.join(p['chips'])}</div></div></article>''' for p in projects)
